package postgres

import (
	"context"
	"time"

	"github.com/TokenFlux/TokenRouter/ent/creativerun"
	"github.com/TokenFlux/TokenRouter/ent/creativerunoutput"
	"github.com/TokenFlux/TokenRouter/internal/creative"
)

// outcome.go records provider outcomes transactionally and completes their
// settlement state.
// A provider success must be recoverable before generated bytes are placed in
// transient storage. Its recorded timestamp, provider identity, output
// metadata, and settlement outbox action are committed in one transaction, so
// a later worker can settle confirmed work without submitting another
// generation merely because delivery persistence failed.
//
// The update compares the run version to reject an intervening writer, and an
// already recorded outcome returns successfully. Cancellation remains a
// distinct task state even when provider work completed: recording keeps
// cancelled status, and final completion can record its cost while retaining
// that status. Result availability then chooses succeeded or result_lost for
// the other recorded outcomes, independently from the captured funds action.

// RecordProviderOutcome commits provider identity, successful-work timing,
// output metadata, and a settlement recovery action together. An existing
// recorded timestamp makes the call return a successful transaction commit
// before rewriting output rows.
//
// Unrecorded outcomes require running or cancelled status and a matching
// version update. Cancelled tasks retain that state while the timestamp still
// makes their provider work billable. Output updates use the transaction
// client, and an error in any row or outbox write rolls the complete
// transaction back. The caller saves image bytes only after this durable
// metadata operation succeeds.
func (r *creativeRunRepository) RecordProviderOutcome(ctx context.Context, id string, providerID int64, outputs []creative.CreativeRunOutput, now time.Time) error {
	tx, err := r.client.Tx(ctx)
	if err != nil {
		return err
	}
	// Any later run, output, or outbox failure leaves this transaction uncommitted.
	// Roll it back on exit; after a successful commit the deferred rollback
	// result is discarded because the transaction is already complete.
	defer func() { _ = tx.Rollback() }()
	current, err := tx.CreativeRun.Query().Where(creativerun.RunIDEQ(id)).Only(ctx)
	if err != nil {
		return translatePersistenceError(err, creative.ErrCreativeRunNotFound, nil)
	}
	if current.ProviderResultRecordedAt != nil {
		return tx.Commit()
	}
	if current.Status != creative.CreativeRunStatusRunning && current.Status != creative.CreativeRunStatusCancelled {
		return creative.ErrCreativeInvalidTransition
	}
	change := tx.CreativeRun.Update().Where(creativerun.IDEQ(current.ID), creativerun.VersionEQ(current.Version)).SetProviderResultRecordedAt(now).SetUpdatedAt(now).AddVersion(1)
	if providerID > 0 {
		change.SetProviderID(providerID)
	}
	if current.Status != creative.CreativeRunStatusCancelled {
		change.SetStatus(creative.CreativeRunStatusProviderSucceeded)
	}
	n, err := change.Save(ctx)
	if err != nil {
		return err
	}
	if n != 1 {
		return creative.ErrCreativeInvalidTransition
	}
	// Bind output writes to the same transaction client as the recorded run.
	// Their metadata and the following settlement outbox entry must publish with
	// that provider-success fact before transient image saves begin.
	participant := &creativeRunRepository{client: tx.Client()}
	for _, output := range outputs {
		if err := tx.CreativeRunOutput.Update().Where(creativerunoutput.RunIDEQ(id), creativerunoutput.OutputIndexEQ(output.OutputIndex)).SetFrameCount(output.FrameCount).Exec(ctx); err != nil {
			return err
		}
		if err := participant.UpdateCreativeRunOutput(ctx, id, output.OutputIndex, output.Status, creative.CreativeDerefString(output.MimeType), creative.CreativeDerefInt64(output.ByteSize), output.TransientExpiresAt, creative.CreativeDerefString(output.ErrorCode), creative.CreativeDerefString(output.ErrorMessage)); err != nil {
			return err
		}
	}
	if err := tx.CreativeRunOutbox.Create().SetRunID(id).SetOperation(string(creative.CreativeRunOutboxSettle)).SetStatus("pending").SetAvailableAt(now).OnConflictColumns("run_id", "operation").DoNothing().Exec(ctx); err != nil {
		return err
	}
	return tx.Commit()
}

// CompleteProviderOutcome records actual cost and a delivered or lost terminal
// result for a recorded provider outcome. Already succeeded or result_lost
// rows return successfully, while an absent recorded timestamp returns an
// invalid transition.
//
// The current version fences the final write against an intervening writer.
// Lost delivery selects result_lost, available delivery selects succeeded, and
// cancelled tasks retain cancelled status while receiving the cost and
// completion time. This operation follows funds capture in Results and updates
// run metadata separately from that billing transaction.
func (r *creativeRunRepository) CompleteProviderOutcome(ctx context.Context, id string, cost float64, lost bool, now time.Time) error {
	current, err := r.client.CreativeRun.Query().Where(creativerun.RunIDEQ(id)).Only(ctx)
	if err != nil {
		return translatePersistenceError(err, creative.ErrCreativeRunNotFound, nil)
	}
	if current.Status == creative.CreativeRunStatusSucceeded || current.Status == creative.CreativeRunStatusResultLost {
		return nil
	}
	if current.ProviderResultRecordedAt == nil {
		return creative.ErrCreativeInvalidTransition
	}
	target := creative.CreativeRunStatusSucceeded
	if lost {
		target = creative.CreativeRunStatusResultLost
	}
	if current.Status == creative.CreativeRunStatusCancelled {
		target = current.Status
	}
	n, err := r.client.CreativeRun.Update().Where(creativerun.IDEQ(current.ID), creativerun.VersionEQ(current.Version)).SetStatus(target).SetActualCost(cost).SetCompletedAt(now).SetUpdatedAt(now).AddVersion(1).Save(ctx)
	if err != nil {
		return err
	}
	if n != 1 {
		return creative.ErrCreativeInvalidTransition
	}
	return nil
}
